      const sockAddr = args[1];
      if (sockAddr.isNull()) {
        return;
      }

      const family = sockAddr.add(1).readU8();
      if (family !== 2) {
        return;
      }

      const rawPort = sockAddr.add(2).readU16();
      const port = ((rawPort >> 8) & 0xFF) | ((rawPort & 0xFF) << 8);

      if (port === 27042) {
        this.shouldBlock = true;
        console.log("[*] Blocking connect() to localhost:" + port);
      }
    },

    onLeave(retval) {
      if (this.shouldBlock) {
        retval.replace(-1);
      }
    }
  });

